#!/usr/bin/env python3
"""Generate typed SysV-to-Windows OpenGL ES 3.0 thunks for the x32 Xbox guest with Microsoft ANGLE backend."""
import re
import sys


def main():
    guest_c, output = sys.argv[1:3]
    text = open(guest_c, encoding="utf-8").read()
    declarations = re.findall(r"^([A-Za-z_][A-Za-z0-9_ \t*]*?)\s+(hostgl_(gl\w+))\((.*?)\);$", text, re.M)
    lines = [
        "/* generated by tools/xbox_host_gl.py; do not edit; Microsoft ANGLE (D3D11 / GLES 3.0) */",
        '#include "host.h"',
        "#include <windows.h>",
        "#include <EGL/egl.h>",
        "#include <GLES3/gl3.h>",
        "#include <GLES3/gl31.h>",
        "#include <GLES3/gl32.h>",
        "#include <GLES2/gl2ext.h>",
        "#include <string.h>",
        "",
        "void *host_gl_resolve(const char *name)",
        "{",
        "    static HMODULE gles;",
        "    void *proc = NULL;",
        "    if (!gles) {",
        '        gles = GetModuleHandleW(L"libGLESv2.dll");',
        '        if (!gles) gles = LoadPackagedLibrary(L"libGLESv2.dll", 0);',
        "    }",
        "    if (gles) {",
        "        proc = (void *)GetProcAddress(gles, name);",
        "    }",
        "    if (!proc) {",
        "        proc = (void *)eglGetProcAddress(name);",
        "    }",
        "    return proc;",
        "}",
        "",
    ]
    names = []
    for ret, host_name, gl_name, params in declarations:
        params = params.strip()
        if gl_name == "glShaderSource":
            lines += [
                f"void GUEST_ABI {host_name}(GLuint shader, GLsizei count, const unsigned long long *strings, const GLint *lengths)",
                "{",
                "    const GLchar *native[16]; GLsizei i;",
                "    typedef void (GL_APIENTRY *proc_t)(GLuint, GLsizei, const GLchar *const *, const GLint *);",
                '    static proc_t proc; if (!proc) proc = (proc_t)host_gl_resolve("glShaderSource");',
                "    if (!proc) return;",
                "    if (count > 16) count = 16; for (i = 0; i < count; ++i) native[i] = (const GLchar *)(uintptr_t)strings[i];",
                "    proc(shader, count, native, lengths);",
                "}", "",
            ]
            names.append((host_name, gl_name))
            continue
        plist = [] if params in ("", "void") else [p.strip() for p in params.split(",")]
        args = []
        named = []
        for i, param in enumerate(plist):
            name = f"a{i}"
            named.append(f"{param} {name}")
            args.append(name)
        signature = ", ".join(named) or "void"
        call = f"proc({', '.join(args)})"
        lines += [
            f"{ret} GUEST_ABI {host_name}({signature})",
            "{",
            f"    typedef {ret} (GL_APIENTRY *proc_t)({params or 'void'});",
            f'    static proc_t proc; if (!proc) proc = (proc_t)host_gl_resolve("{gl_name}");',
            f"    if (!proc) return{' (' + ret + ')0' if ret != 'void' else ''};",
            f"    {'return ' if ret != 'void' else ''}{call};",
            "}", "",
        ]
        names.append((host_name, gl_name))

    lines += [
        "static const struct { const char *name; void *function; } xbox_gl_imports[] = {",
        *[f'    {{ "{gl}", (void *){host} }},' for host, gl in names],
        "};", "",
        "void GUEST_ABI host_gl_get_string(uint32_t name, int index, char *buffer, uint32_t size)",
        "{",
        "    typedef const GLubyte *(GL_APIENTRY *p_glGetString)(GLenum);",
        "    typedef const GLubyte *(GL_APIENTRY *p_glGetStringi)(GLenum, GLuint);",
        "    static p_glGetString p_gs;",
        "    static p_glGetStringi p_gsi;",
        "    const GLubyte *text = NULL;",
        '    if (!p_gs) p_gs = (p_glGetString)host_gl_resolve("glGetString");',
        '    if (!p_gsi) p_gsi = (p_glGetStringi)host_gl_resolve("glGetStringi");',
        "    if (index >= 0 && p_gsi) text = p_gsi(name, (GLuint)index);",
        "    else if (p_gs) text = p_gs(name);",
        "    if (size && buffer) {",
        "        buffer[0] = 0;",
        "        if (text) {",
        "            strncpy(buffer, (const char *)text, size - 1);",
        "            buffer[size - 1] = 0;",
        "        }",
        "    }",
        "}", "",
        "int GUEST_ABI host_gl_has_extension(const char *name)",
        "{",
        "    typedef void (GL_APIENTRY *p_glGetIntegerv)(GLenum, GLint *);",
        "    typedef const GLubyte *(GL_APIENTRY *p_glGetStringi)(GLenum, GLuint);",
        "    typedef const GLubyte *(GL_APIENTRY *p_glGetString)(GLenum);",
        "    static p_glGetIntegerv p_giv;",
        "    static p_glGetStringi p_gsi;",
        "    static p_glGetString p_gs;",
        "    if (!name || !*name) return 0;",
        "    /* Prune desktop OpenGL 4.5 extensions unsupported by ANGLE GLES 3.0 */",
        '    if (!strncmp(name, "GL_ARB_", 7)) return 0;',
        '    if (!strncmp(name, "WGL_", 4)) return 0;',
        '    if (!strcmp(name, "GL_EXT_polygon_offset_clamp")) return 0;',
        '    if (!p_giv) p_giv = (p_glGetIntegerv)host_gl_resolve("glGetIntegerv");',
        '    if (!p_gsi) p_gsi = (p_glGetStringi)host_gl_resolve("glGetStringi");',
        '    if (!p_gs) p_gs = (p_glGetString)host_gl_resolve("glGetString");',
        "    if (p_giv && p_gsi) {",
        "        GLint count = 0, i;",
        "        p_giv(GL_NUM_EXTENSIONS, &count);",
        "        for (i = 0; i < count; ++i) {",
        "            const char *ext = (const char *)p_gsi(GL_EXTENSIONS, (GLuint)i);",
        "            if (ext && !strcmp(ext, name)) return 1;",
        "        }",
        "    } else if (p_gs) {",
        "        const char *extensions = (const char *)p_gs(GL_EXTENSIONS);",
        "        if (extensions) {",
        "            const char *start = extensions;",
        "            size_t len = strlen(name);",
        "            while ((start = strstr(start, name)) != NULL) {",
        "                if ((start == extensions || start[-1] == ' ') &&",
        "                    (start[len] == ' ' || start[len] == '\\0'))",
        "                    return 1;",
        "                start += len;",
        "            }",
        "        }",
        "    }",
        "    return 0;",
        "}", "",
        "uint32_t GUEST_ABI host_gl_read_buffer_word(uint32_t buffer, uint32_t offset)",
        "{",
        "    uint32_t value = 0;",
        "    GLint previous = 0;",
        "    const void *mapping;",
        "    typedef void (GL_APIENTRY *p_glGetIntegerv)(GLenum, GLint *);",
        "    typedef void (GL_APIENTRY *p_glBindBuffer)(GLenum, GLuint);",
        "    typedef void *(GL_APIENTRY *p_glMapBufferRange)(GLenum, GLintptr, GLsizeiptr, GLbitfield);",
        "    typedef GLboolean (GL_APIENTRY *p_glUnmapBuffer)(GLenum);",
        "    static p_glGetIntegerv p_get_int;",
        "    static p_glBindBuffer p_bind_buf;",
        "    static p_glMapBufferRange p_map_buf;",
        "    static p_glUnmapBuffer p_unmap_buf;",
        '    if (!p_get_int) p_get_int = (p_glGetIntegerv)host_gl_resolve("glGetIntegerv");',
        '    if (!p_bind_buf) p_bind_buf = (p_glBindBuffer)host_gl_resolve("glBindBuffer");',
        '    if (!p_map_buf) p_map_buf = (p_glMapBufferRange)host_gl_resolve("glMapBufferRange");',
        '    if (!p_unmap_buf) p_unmap_buf = (p_glUnmapBuffer)host_gl_resolve("glUnmapBuffer");',
        "    if (p_get_int && p_bind_buf && p_map_buf && p_unmap_buf) {",
        "        p_get_int(GL_ATOMIC_COUNTER_BUFFER_BINDING, &previous);",
        "        p_bind_buf(GL_ATOMIC_COUNTER_BUFFER, buffer);",
        "        mapping = p_map_buf(GL_ATOMIC_COUNTER_BUFFER, offset, sizeof(value), GL_MAP_READ_BIT);",
        "        if (mapping) {",
        "            memcpy(&value, mapping, sizeof(value));",
        "            p_unmap_buf(GL_ATOMIC_COUNTER_BUFFER);",
        "        }",
        "        p_bind_buf(GL_ATOMIC_COUNTER_BUFFER, (GLuint)previous);",
        "    }",
        "    return value;",
        "}", "",
        "uint32_t GUEST_ABI host_gl_read_buffer(uint32_t buffer, uint32_t offset)",
        "{",
        "    return host_gl_read_buffer_word(buffer, offset);",
        "}", "",
        "void GUEST_ABI host_gl_buffer_write(uint32_t target, uint32_t offset, uint32_t size, const void *data)",
        "{",
        "    typedef void *(GL_APIENTRY *p_glMapBufferRange)(GLenum, GLintptr, GLsizeiptr, GLbitfield);",
        "    typedef GLboolean (GL_APIENTRY *p_glUnmapBuffer)(GLenum);",
        "    typedef void (GL_APIENTRY *p_glBufferSubData)(GLenum, GLintptr, GLsizeiptr, const void *);",
        "    static p_glMapBufferRange p_map;",
        "    static p_glUnmapBuffer p_unmap;",
        "    static p_glBufferSubData p_sub;",
        '    if (!p_map) p_map = (p_glMapBufferRange)host_gl_resolve("glMapBufferRange");',
        '    if (!p_unmap) p_unmap = (p_glUnmapBuffer)host_gl_resolve("glUnmapBuffer");',
        '    if (!p_sub) p_sub = (p_glBufferSubData)host_gl_resolve("glBufferSubData");',
        "    if (p_map && p_unmap) {",
        "        void *mapping = p_map(target, offset, size, GL_MAP_WRITE_BIT | GL_MAP_UNSYNCHRONIZED_BIT);",
        "        if (mapping) {",
        "            memcpy(mapping, data, size);",
        "            p_unmap(target);",
        "            return;",
        "        }",
        "    }",
        "    if (p_sub) {",
        "        p_sub(target, offset, size, data);",
        "    }",
        "}", "",
        "#define FRAME_FENCE_SLOTS 8",
        "static GLsync frame_fences[FRAME_FENCE_SLOTS];", "",
        "void GUEST_ABI host_gl_fence_frame(uint32_t slot)",
        "{",
        "    typedef GLsync (GL_APIENTRY *p_glFenceSync)(GLenum, GLbitfield);",
        "    typedef void (GL_APIENTRY *p_glDeleteSync)(GLsync);",
        "    static p_glFenceSync p_fence;",
        "    static p_glDeleteSync p_del;",
        '    if (!p_fence) p_fence = (p_glFenceSync)host_gl_resolve("glFenceSync");',
        '    if (!p_del) p_del = (p_glDeleteSync)host_gl_resolve("glDeleteSync");',
        "    if (slot >= FRAME_FENCE_SLOTS || !p_fence) return;",
        "    if (frame_fences[slot] && p_del) p_del(frame_fences[slot]);",
        "    frame_fences[slot] = p_fence(GL_SYNC_GPU_COMMANDS_COMPLETE, 0);",
        "}", "",
        "void GUEST_ABI host_gl_wait_frame(uint32_t slot)",
        "{",
        "    typedef GLenum (GL_APIENTRY *p_glClientWaitSync)(GLsync, GLbitfield, GLuint64);",
        "    typedef void (GL_APIENTRY *p_glDeleteSync)(GLsync);",
        "    static p_glClientWaitSync p_wait;",
        "    static p_glDeleteSync p_del;",
        '    if (!p_wait) p_wait = (p_glClientWaitSync)host_gl_resolve("glClientWaitSync");',
        '    if (!p_del) p_del = (p_glDeleteSync)host_gl_resolve("glDeleteSync");',
        "    if (slot >= FRAME_FENCE_SLOTS || !frame_fences[slot] || !p_wait) return;",
        "    p_wait(frame_fences[slot], GL_SYNC_FLUSH_COMMANDS_BIT, 1000000000ull);",
        "    if (p_del) p_del(frame_fences[slot]);",
        "    frame_fences[slot] = NULL;",
        "}",
    ]
    with open(output, "w", encoding="utf-8") as out:
        out.write("\n".join(lines) + "\n")


if __name__ == "__main__":
    main()
